/*!
 * wega-music-chase5.js - Lap 5 chase add-on for the Wega's Challenge music pack.
 * Load AFTER wega-music.js and BEFORE the game module. It registers a "chase5" track with
 * WegaMusic so WegaMusic.init() decodes it with the others and WegaMusic.play("chase5") works.
 * The Lap 5 chase (WEGA, DESTROYER OF WORLDS) lasts exactly as long as this song.
 * Track: FORGET ME NOT (Asriel vs Dess, DELTARUNE UST) - supplied by the player.
 */
(function (global) {
  "use strict";
  var D = global.WEGA_MUSIC_DATA, W = global.WegaMusic;
  if (!D || !W) { if (global.console) console.warn("[wega-music-chase5] load wega-music.js first"); return; }
  D.chase5 = {
    title: "Forget Me Not (Lap 5 Chase Theme)",
    credit: "FORGET ME NOT - Asriel vs Dess, DELTARUNE UST",
    duration: 196.0,
    loopStart: 0.03,
    loopEnd: 194.3,
    gain: 0.85,
    src: "data:audio/mpeg;base64,"
  };
  if (W.tracks.indexOf("chase5") < 0) W.tracks.push("chase5");
})(typeof window !== "undefined" ? window : globalThis);
